select 'maintenance', 'Emrill Services LLC (mplus Home Maintenance)', 'Emrill Services LLC (mplus Home Maintenance)', 'دبي', 'Airport Road', '800 367455', 'https://www.emrill.com', 2002, 'شركة إدارة مرافق متكاملة في الإمارات، تقدم صيانة المنازل عبر قسم mplus (تكييف وسباكة وكهرباء وأعمال عامة).', 'https://www.emrill.com/mplus-home-maintenance/', 'إمريل شركة لإدارة المرافق المتكاملة تقدم خدمات الإدارة الفنية والخدمات العامة والأمن، وتأسست كمشروع مشترك بين إعمار العقارية وكاريليون. أطلقت عام 2011 قسم mplus لصيانة المنازل والعقارات بعقود سنوية أو خدمات منفردة مع مكتب مساعدة على مدار الساعة. تحمل شهادات ISO 9001 وISO 14001 وISO 45001 وISO 41001.', 'https://www.emrill.com/wp-content/uploads/2019/08/Emrill-Logo-100px.png', 'info@emrill.com', 'SR04 مبنى مكين، شارع المطار، ص.ب 38083، دبي، الإمارات', null, array['صيانة التكييف والسباكة والكهرباء', 'تنظيف خزانات المياه ومكافحة الآفات', 'عملاء: إعمار وميراس ووصل', 'دبي أوبرا', 'عقود صيانة سنوية للمنازل']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'maintenance' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Emrill Services LLC (mplus Home Maintenance)'));
