select 'security', 'Emirates Captain Safety & Security Devices LLC', 'Emirates Captain Safety & Security Devices LLC', 'أبوظبي', 'مصفح', '+97125550670', 'https://www.emiratescaptain.com', null, 'شركة لأنظمة الحماية من الحريق والإنذار وتعبئة الطفايات والفحص والصيانة.', 'https://www.emiratescaptain.com/', 'تقدم كابتن الإمارات أنظمة الحماية من الحريق وكشف وإنذار الحريق وتعبئة الطفايات والإنارة الطارئة والفحص والصيانة، وتذكر أنها معتمدة من الدفاع المدني بدرجة A+. لها مكاتب في أبوظبي ودبي والعين ورأس الخيمة والشارقة.', null, 'info@emiratescaptain.ae', 'مصفح، أبوظبي، ص.ب 133358', null, array['أنظمة إنذار الحريق', 'أنظمة الرشاشات', 'تعبئة طفايات الحريق', 'الإنارة الطارئة ولوحات المخارج', 'مضخات الحريق']::text[], null, true
